package org.jetlinks.pro.property.quality.service;
import org.junit.jupiter.api.Test;
import org.hswebframework.web.exception.BusinessException;
import org.jetlinks.pro.property.quality.entity.*;
import java.time.*;import java.util.*;import java.math.*;
import static org.junit.jupiter.api.Assertions.*;
class QualityRulesTest {
 private static long at(String text){return LocalDateTime.parse(text).atZone(QualityScheduleRules.ZONE).toInstant().toEpochMilli();}
 private static QualityRecordEntity score(String line,int value){var r=new QualityRecordEntity();r.setSubjectParentId(line);r.setScore(value);return r;}
 @Test void zeroPointItemsAcceptNegativeDeductions(){assertDoesNotThrow(()->QualityScoring.validateScore(0,-5));assertThrows(BusinessException.class,()->QualityScoring.validateScore(0,1));}
 @Test void positiveItemsCannotExceedOriginalOrBeNegative(){assertDoesNotThrow(()->QualityScoring.validateScore(10,0));assertDoesNotThrow(()->QualityScoring.validateScore(10,10));assertThrows(BusinessException.class,()->QualityScoring.validateScore(10,11));assertThrows(BusinessException.class,()->QualityScoring.validateScore(10,-1));}
 @Test void companyWeightsMatchLegacyFourDecimalIntermediateAndIntegerRounding(){var rows=List.of(score("environment",99),score("security",98));var weights=List.<Map<String,Object>>of(Map.of("subjectParentId","environment","weight",new BigDecimal("33.33")),Map.of("subjectParentId","security","weight",new BigDecimal("66.67")));assertEquals(98,QualityScoring.total(1,rows,weights));assertEquals(197,QualityScoring.total(2,rows,weights));}
 @Test void weightedHalvesRoundUp(){assertEquals(1,QualityScoring.total(1,List.of(score("line",1)),List.of(Map.of("subjectParentId","line","weight",50))));}
 @Test void incompleteOrDuplicateWeightsAreRejected(){var snapshots=List.<Map<String,Object>>of(Map.of("subjectParentId","a"),Map.of("subjectParentId","b"));assertThrows(BusinessException.class,()->QualityScoring.validateWeights(1,snapshots,List.of(Map.of("subjectParentId","a","weight",100))));assertThrows(BusinessException.class,()->QualityScoring.validateWeights(1,snapshots,List.of(Map.of("subjectParentId","a","weight",50),Map.of("subjectParentId","a","weight",50))));}
 @Test void weightTotalMustBeExactly100(){var snapshots=List.<Map<String,Object>>of(Map.of("subjectParentId","a"));assertThrows(BusinessException.class,()->QualityScoring.validateWeights(1,snapshots,List.of(Map.of("subjectParentId","a","weight",99))));assertDoesNotThrow(()->QualityScoring.validateWeights(1,snapshots,List.of(Map.of("subjectParentId","a","weight",100))));}
 @Test void fixedDailyScheduleAndDynamicDeadlineSurviveMonthBoundary(){var t=new QualityTaskEntity();t.setTaskLevel(1);t.setTaskType(2);t.setStartTime(at("2028-02-28T00:00"));t.setEndTime(at("2028-03-01T23:59"));t.setFirstGenerateTime(at("2028-02-28T09:00"));t.setIntervalValue(1);t.setIntervalUnit(3);t.setReportDeadlineValue(2);t.setReportDeadlineUnit("HOUR");var slots=QualityScheduleRules.build(t);assertEquals(3,slots.size());assertEquals(at("2028-02-29T09:00"),slots.get(1).time());assertEquals(at("2028-02-29T11:00"),slots.get(1).end());assertEquals(slots,QualityScheduleRules.build(t));}
 @Test void temporaryScheduleGeneratesExactlyOneBatch(){var t=new QualityTaskEntity();t.setTaskLevel(1);t.setTaskType(1);t.setFirstGenerateTime(at("2026-11-04T09:00"));t.setReportDeadline(at("2026-11-05T09:00"));assertEquals(1,QualityScheduleRules.build(t).size());}
 private QualityTaskEntity project(int frequency,String start,String end){var t=new QualityTaskEntity();t.setTaskLevel(2);t.setTaskType(2);t.setStartTime(at(start));t.setEndTime(at(end));t.setInspectionFrequency(frequency);t.setOperationFrequency(1);return t;}
 @Test void dailyScheduleRequiresExactFrequencyWithinEachDay(){var t=project(1,"2026-11-04T00:00","2026-11-05T23:59");t.setScheduleRules(Map.of("dayTimes",List.of("09:00")));assertEquals(2,QualityScheduleRules.build(t).size());t.setOperationFrequency(2);assertThrows(BusinessException.class,()->QualityScheduleRules.build(t));}
 @Test void duplicateDailyTimesAreRejected(){var t=project(1,"2026-11-04T00:00","2026-11-05T23:59");t.setOperationFrequency(2);t.setScheduleRules(Map.of("dayTimes",List.of("09:00","09:00")));assertThrows(BusinessException.class,()->QualityScheduleRules.build(t));}
 @Test void partialWeekClipsOutsideDateRange(){var t=project(2,"2026-11-04T00:00","2026-11-10T23:59");t.setScheduleRules(Map.of("weekTimes",List.of(Map.of("weekDay",1,"time","09:00"))));var slots=QualityScheduleRules.build(t);assertEquals(1,slots.size());assertEquals(at("2026-11-09T09:00"),slots.get(0).time());assertEquals(at("2026-11-10T23:59"),slots.get(0).end());}
 @Test void monthlyPlanUsesRealLeapDay(){var t=project(3,"2028-02-01T00:00","2028-03-31T23:59");t.setScheduleRules(Map.of("monthDateTimes",List.of("2028-02-29 09:00","2028-03-31 09:00")));var slots=QualityScheduleRules.build(t);assertEquals(2,slots.size());assertEquals(at("2028-02-29T09:00"),slots.get(0).time());}
 @Test void monthlyPlanRejectsTooManyTimesInOneMonth(){var t=project(3,"2028-02-01T00:00","2028-02-29T23:59");t.setScheduleRules(Map.of("monthDateTimes",List.of("2028-02-15 09:00","2028-02-29 09:00")));assertThrows(BusinessException.class,()->QualityScheduleRules.build(t));}
 @Test void snapshotsRejectFractionalOrOutOfRangeScores(){assertThrows(BusinessException.class,()->QualityConfigurationRules.score(new BigDecimal("1.5")));assertThrows(BusinessException.class,()->QualityConfigurationRules.score(101));assertThrows(BusinessException.class,()->QualityConfigurationRules.score(-1));}
 @Test void recordScopeInheritanceDoesNotUseSubmittedCreator(){var c=new QualityContext("tenant-a","app-a","u","U");var task=QualityScope.initialize(new QualityTaskEntity(),c);task.setProjectId("project-a");task.setOrganizationId("project-a");var record=QualityScope.initialize(new QualityRecordEntity(),c);QualityScope.inherit(record,task);assertEquals("tenant-a",record.getTenantId());assertEquals("app-a",record.getApplicationId());assertEquals("project-a",record.getOrganizationId());assertFalse(record.getDeleted());assertEquals(0,record.getVersion());}
}
